{
  "status": "SUPPORTED",
  "task_summary": "Identify compatible components, fasten target, place tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "The object at the workbench location that requires fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": [
        "object",
        "assembly"
      ],
      "required_properties": [
        "needs fastening"
      ]
    },
    {
      "id": "fastening_component",
      "entity_kind": "OBJECT",
      "function": "The hardware part used to secure the target.",
      "required_count": 1,
      "binding_policy": "DISTINCT"
      ,
      "candidate_categories": [
        "part",
        "hardware",
        "connector"
      ],
      "required_properties": [
        "compatible with target",
        "usable for fastening"
      ]
    },
    {
      "id": "fastening_tool",
      "entity_kind": "OBJECT",
      "function": "The implement used to perform the fastening.",
      "required_count": 1,
      "binding_policy": "REUSABLE"
      ,
      "candidate_categories": [
        "tool",
        "implement"
      ],
      "required_properties": [
        "usable for fastening",
        "reusable"
      ]
    },
    {
      "id": "workbench",
      "entity_kind": "REGION",
      "function": "The surface where the task occurs and equipment is left.",
      "required_count": 1,
      "binding_policy": "SHARED"
      ,
      "candidate_categories": [
        "table",
        "surface"
      ],
      "required_properties": [
        "supports objects",
        "flat surface"
      ]
    }
  ],
  "functional_relations": [
    {
      "id": "fastening_relation",
      "relation": "fastening_component fits onto fastening_target",
      "participant_roles": [
        "fastening_component",
        "fastening_target"
      ]
    ,
      "required": true
    },
    {
      "id": "tool_usage_relation",
      "relation": "fastening_tool is used to fasten fastening_component to fastening_target",
      "participant_roles": [
        "fastening_tool",
        "fastening_component",
        "fastening_target"
      ]
    ,
      "required": true
    },
    {
      "id": "placement_relation",
      "relation": "fastening_tool is placed on workbench",
      "participant_roles": [
        "fastening_tool",
        "workbench"
      ]
    ,
      "required": true
    }
  ],
  "operation_pairings": [
    {
      "id": "fasten_operation",
      "operation": "fasten fastening_component to fastening_target",
      "participant_roles": [
        "fastening_component",
        "fastening_target"
      ],
      "operation_count": 1
    },
    {
      "id": "place_operation",
      "operation": "place fastening_tool on workbench",
      "participant_roles": [
        "fastening_tool",
        "workbench"
      ],
      "operation_count": 1
    }
  ]
},
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {"label": "black tray on table", "visual_description": "Black rectangular tray with yellow and blue items on top."},
        {"label": "blue cabinet", "visual_description": "Blue cabinet standing on the table."}
      ],
      "fastening_component": [
        {"label": "yellow/blue items on tray", "visual_description": "Small yellow and blue rectangular items on the tray."}
      ],
      "fastening_tool": [
        {"label": "none clearly visible", "visual_description": "No tool is clearly identifiable on the table surface."}
      ],
      "workbench": [
        {"label": "wooden table", "visual_description": "Wooden table with drawers underneath."}
      ]
    },
    "inspectable_regions": [
      {
        "id": "drawers_under_table",
        "label": "drawers_under_table",
        "visual_description": "Two blue drawers under the table.",
        "reason": "Closed storage structure, likely contains tools or components."
      },
      {
        "id": "cabinet_on_table",
        "label": "cabinet_on_table",
        "visual_description": "Blue cabinet on the table.",
        "reason": "Closed storage structure, likely contains tools or components."
      }
    ],
    "inspection_order": [
      "drawers_under_table",
      "cabinet_on_table"
    ]
  }
,
  "unsupported_reason": ""
,
  "schema_version": 3
}
